import 'dart:async';
import 'dart:js_interop';
import 'dart:js_interop_unsafe';

// Generated by `dart run dwi_builder:dwi build`; not committed.
import 'dwi_tasks.g.dart';
import 'tasks.dart';

@JS('document')
external JSObject get _document;

void main() {
  unawaited(_run());
}

Future<void> _run() async {
  final output =
      _document.callMethod('getElementById'.toJS, 'output'.toJS) as JSObject;
  output.setProperty(
    'textContent'.toJS,
    'Running calculatePrimes(2000000) in a worker...'.toJS,
  );

  final watch = Stopwatch()..start();
  try {
    final count = await DwiTasks.calculatePrimes(2000000);
    // Registered static selection (ADR-020): choose a task at run time by its
    // tear-off. The generated registry maps it to the same typed proxy as
    // `DwiTasks.Greetings$describe`; no function is sent to the worker.
    final String Function(String) task = count.isEven
        ? describe
        : Greetings.describe;
    final greeting = await DwiFunctions.run(task, 'DWI');
    // A record carries several typed values, here an int and an enum, into
    // one task (ADR-021). The generator writes the conversion.
    final summary = await DwiFunctions.run(summarise, (100000, Detail.full));
    // A stream task reports progress as it runs (ADR-022).
    final progress = <int>[
      await for (final found in DwiTasks.primeProgress(100000)) found,
    ];
    output.setProperty(
      'textContent'.toJS,
      '$greeting Primes: $count (${watch.elapsedMilliseconds} ms). '
              '$summary. Progress: ${progress.join(' → ')}.'
          .toJS,
    );
  } catch (error, stack) {
    output.setProperty('textContent'.toJS, 'Error: $error\n$stack'.toJS);
  }
}
